<script setup lang="ts">import {computed} from 'vue';import type {Task,CPM} from '../types/domain';import {num} from '../utils/format';const props=defineProps<{tasks:Task[];edges:string[][];baseline?:CPM}>();const layout=computed(()=>{const ids=props.tasks.map(t=>t.task_id).sort(),level:Record<string,number>={},pending=new Set(ids);for(let i=0;i<=ids.length&&pending.size;i++){for(const id of [...pending]){const pred=props.edges.filter(e=>e[1]===id).map(e=>e[0]);if(pred.every(p=>level[p]!==undefined)){level[id]=pred.length?Math.max(...pred.map(p=>level[p]))+1:0;pending.delete(id)}}}for(const id of pending)level[id]=0;const groups:Record<number,string[]>={};ids.forEach(id=>(groups[level[id]]??=[]).push(id));const pos:Record<string,{x:number;y:number}>={};Object.entries(groups).forEach(([l,group])=>group.forEach((id,i)=>pos[id]={x:25+Number(l)*172,y:40+i*94}));const width=Math.max(740,70+(Math.max(0,...Object.values(level))+1)*172),height=90+Math.max(1,...Object.values(groups).map(g=>g.length))*94;return {pos,width,height}});const nodes=computed(()=>props.tasks.slice().sort((a,b)=>a.task_id.localeCompare(b.task_id)));const row=(id:string)=>props.baseline?.tasks.find(t=>t.task_id===id);function critical(a:string,b:string){return props.baseline?.critical_edges.some(e=>e[0]===a&&e[1]===b)}function edgePath(a:string,b:string){const p=layout.value.pos[a],q=layout.value.pos[b],x1=p.x+136,y1=p.y+32,x2=q.x,y2=q.y+32;return `M${x1},${y1} H${(x1+x2)/2} V${y2} H${x2}`}</script><template><div class="graph-legend"><span><i class="critical-key"/>基线关键任务/连接</span><span><i/>普通FS依赖</span><span>节点工期 m / 小时 · ES→EF / 小时</span></div><div class="dag-scroll"><svg :width="layout.width" :height="layout.height" role="img" aria-label="工作包FS依赖图"><defs><marker id="arrow-normal" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 L10 5 L0 10Z" fill="#9e9a8d"/></marker><marker id="arrow-critical" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 L10 5 L0 10Z" fill="#ad704c"/></marker></defs><path v-for="e in edges" :key="e.join('|')" :d="edgePath(e[0],e[1])" fill="none" :stroke="critical(e[0],e[1])?'#ad704c':'#b5b0a2'" :stroke-width="critical(e[0],e[1])?2.6:1.2" :marker-end="critical(e[0],e[1])?'url(#arrow-critical)':'url(#arrow-normal)'"><title>{{e[0]}} → {{e[1]}} / FS零等待</title></path><g v-for="t in nodes" :key="t.task_id" :transform="`translate(${layout.pos[t.task_id].x},${layout.pos[t.task_id].y})`"><rect width="136" height="65" :fill="row(t.task_id)?.critical?'#e9d7bd':'#f1efe3'" :stroke="row(t.task_id)?.critical?'#ad704c':'#bcb7a7'" :stroke-width="row(t.task_id)?.critical?2:1"/><text x="10" y="19" class="node-id">{{t.task_id}} <tspan x="125" text-anchor="end">{{num(t.m,1)}}h</tspan></text><text x="10" y="38" class="node-name">{{t.name}}</text><text x="10" y="55" class="node-time">{{row(t.task_id)?num(row(t.task_id)!.es,1)+' → '+num(row(t.task_id)!.ef,1):'a '+num(t.a,1)+' / b '+num(t.b,1)}}</text></g></svg></div><p class="muted">只表达零等待finish-start依赖；虚拟源连接所有起点，所有终点连接共同虚拟汇，孤立任务同时连接两端。大图可内部横向滚动。</p></template>